"""5571: контракт виведеного producer-сценарію, зовнішній щабель, unknown і точна адреса тіні; не LIVE.
Смуга й ціль — не числа в пробі, а те, що бачать пул і суд: `смуга_ошатності` сцени суду (штамп `сценарій`, рядок 9042)
і `ціль_поломки_ошатності` від неї; щабель драбини міняється — проба меряє те саме."""
import pathlib, sys
sys.path.insert(0, str(pathlib.Path(__file__).resolve().parent.parent))
import поломки as П, формальність as Ф, внутрішня_мова as В, composer as К
ОШАТНІСТЬ = [4, 6]   # число мовної моделі
сц = Ф.сценарій(місце='ресторан', нагода='побачення', смуга=Ф.смуга_ошатності(dict(ошатність=ОШАТНІСТЬ)))
смуга = tuple(Ф.смуга_ошатності(сц)[:2]); ціль = П.ціль_поломки_ошатності(смуга)
# одне джерело: смуга суду = смуга пулу = `діапазон` сцени
assert смуга == tuple(Ф.смуга_ошатності(dict(ошатність=ОШАТНІСТЬ))[:2]) == tuple(сц['діапазон']) and ціль
with П.прогін(П.ЗА_ІД['K-KOH-02']['коди']) as прогін_блоку_12:
    е = [dict(річ='верх-фікстура', слот='верх', формальність=смуга[0]), dict(річ='низ-фікстура', слот='низ', формальність=смуга[1])]
    повний = [e["річ"] for e in е] + ["пальто-фікстура", "взуття-фікстура", "сумка-фікстура"]
    з = Ф.формальність_образу(е, сц, ід_образу=повний, прогін_руки=прогін_блоку_12)
    assert П.тінь_образу(П.тінь(прогін_руки=прогін_блоку_12), повний) and not П.тінь_образу(П.тінь(прогін_руки=прогін_блоку_12), [e["річ"] for e in е])
    активні = [x for x in з if x.get('правило') == 'K-KOH-02' and x.get('ремонт_заяви')]
    assert активні and активні[0]['сила_нп'] > 0 and активні[0]['ремонт_заяви'][0]['values']['band'] == list(ціль)
    assert П._хибний_щабель((3, 5), (4, 6), (3, 3)) is False
    assert П._хибний_щабель((2, 3), (4, 6), (3, 3)) is True
    assert П.ціль_поломки_ошатності((1, 10)) is None
    assert П.злам('K-KOH-02', 'смуга', смуга, прогін_руки=прогін_блоку_12) == ціль
    кат = [dict(id='нормальна', слот='верх', формальність=смуга[0]), dict(id='хибна', слот='верх', формальність=ціль[0]), dict(id='невідома', слот='верх')]
    пул, геть, _ = К.поза_сценою(кат, dict(ошатність=ОШАТНІСТЬ), прогін_руки=прогін_блоку_12)
    assert {r['id'] for r in пул} == {'хибна', 'невідома'} and [r['id'] for r in геть] == ['нормальна']
    assert П.вхід(П.ЗА_ІД['K-KOH-02'], dict(сценарій=dict()))[0] is False
    # без смуги прогону (ні числа, ні письмової вимоги) суд руки 2 не ламається — як і пул (рядок 9042)
    сц_без = Ф.сценарій(місце='ресторан', нагода='побачення'); з_без = Ф.формальність_образу(е, сц_без, ід_образу=повний, прогін_руки=прогін_блоку_12)
    assert Ф.смуга_ошатності(сц_без) is None and not any(x.get('правило') == 'K-KOH-02' and x.get('ремонт_заяви') for x in з_без)
with П.прогін(П.ЗА_ІД['K-KOH-02']['коди']) as прогін_блоку_30:
    з = Ф.формальність_образу([dict(річ='невідомий-верх', слот='верх'), dict(річ='невідомий-низ', слот='низ')], сц, прогін_руки=прогін_блоку_30)
    assert not П.тінь(прогін_руки=прогін_блоку_30) and any(x.get('без_входу') and x.get('сила_нп') == 0 for x in з)
with П.прогін(П.ЗА_ІД['K-CRA-01']['коди']) as прогін_блоку_33:
    адресат = dict(id='третя-фікстура'); образ = ['верх-фікстура', 'низ-фікстура', адресат['id']]
    зн = П._хибна_знахідка('K-CRA-01', [адресат], 'require_third_piece', 'omit_third_piece', 'remove_items', В.заява('remove_this_item'), образ, прогін_руки=прогін_блоку_33)
    повна = П.тінь_образу(П.тінь(прогін_руки=прогін_блоку_33), образ); підмножина = П.тінь_образу(П.тінь(прогін_руки=прогін_блоку_33), [адресат['id']])
    assert not підмножина and len(повна) == 1
    assert повна[0]['сила'] == зн['сила'] and повна[0]['сила_нп'] == зн['сила_нп'] and повна[0]['суть'] == зн['суть']
    assert повна[0]['речі'] == [адресат['id']]
import аксесуари_носіння as АН   # хвиля 21: тінь хибної поради без образу лягає в точці збору з повним складом
with П.прогін(('K-SHO-16',)) as прогін_блоку_41:
    пласка, висока, невідома = dict(id='пласка', слот='взуття', каблук=False, каблук_см=0.0), dict(id='висока', слот='взуття', каблук_см=9.0), dict(id='невідома', слот='взуття', каблук=True)
    з = АН.вартість_носіння([пласка, висока, невідома], тривалість_год=9, поверхня='бруківка', прогін_руки=прогін_блоку_41); образ = ['верх-ф', 'низ-ф', 'пласка', 'висока', 'невідома']
    лишились = П.відсіяти(з, образ, прогін_руки=прогін_блоку_41); т = П.тінь_образу(П.тінь(прогін_руки=прогін_блоку_41), образ)
    assert {(x['дія'], tuple(x['речі'])) for x in т} == {('target_high_heel', ('пласка',)), ('drop_correct_advice', ('висока',))}
    assert all(x.get('правило') != 'K-SHO-16' or x.get('сила') == 'питання' or x['речі'] == ['пласка'] for x in лишились) and any(x.get('сила') == 'питання' for x in лишились)
assert АН.вартість_носіння([пласка], тривалість_год=9, поверхня='бруківка') == [] and not П.тінь() and not П.зламані()
print('5571: producer-діапазон / зовнішня ціль / чесний unknown / full-outfit shadow / тінь у точці збору — зелені')
